// src/commands.js
function commandsFor(live, reveal) {
  const pet = () => live.get()?.pet ?? null;
  return [
    { id: "show", label: "Hermes Pok\xE9mon: Show the garden", keywords: ["pokemon", "garden", "companion"], run: () => reveal() },
    { id: "pet", label: "Hermes Pok\xE9mon: Pet", keywords: ["pokemon", "pet", "companion"], run: () => Boolean(pet()?.pet()) },
    { id: "ball", label: "Hermes Pok\xE9mon: Throw the ball", keywords: ["pokemon", "ball", "fetch"], run: () => Boolean(pet()?.throwBall()) },
    { id: "berry", label: "Hermes Pok\xE9mon: Give a berry", keywords: ["pokemon", "berry", "treat"], run: () => Boolean(pet()?.giveTreat()) }
  ];
}

